import { Injectable, signal } from '@angular/core';
import { Hotel } from '../models/hotel.model';
import { delay, of, Observable } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class HotelService {
  private hotels = signal<Hotel[]>([
    {
      id: 1,
      name: 'Sea View Resort Ratnagiri',
      location: 'Ratnagiri Beach',
      rating: 4.6,
      reviews: 1250,
      price: 4599,
      stars: 4,
      image: 'data:image/jpeg;base64,',
      amenities: ['WiFi', 'Pool', 'Beachfront', 'AC'],
      description: 'Luxury beachfront resort with stunning Arabian Sea views and modern amenities.'
    },
    {
      id: 2,
      name: 'Ganpatipule Heritage Hotel',
      location: 'Ganpatipule',
      rating: 4.4,
      reviews: 890,
      price: 3899,
      stars: 3,
      image: 'data:image/jpeg;base64,',
      amenities: ['Pool', 'Restaurant', 'Garden', 'Free Parking'],
      description: 'Traditional Konkani hospitality meets modern comfort near Ganpatipule Temple.'
    },
    {
      id: 3,
      name: 'Alibaug Beach Palace',
      location: 'Alibaug',
      rating: 4.7,
      reviews: 2100,
      price: 5499,
      stars: 5,
      image: 'data:image/jpeg;base64,',
      amenities: ['Private Beach', 'Spa', 'Gym', 'Infinity Pool'],
      description: '5-star luxury palace right on Alibaug beach with world-class facilities.'
    },
    // More hotels
    ...Array.from({length: 17}, (_, i) => ({
      id: i + 4,
      name: `Konkan Hotel ${i + 4}`,
      location: ['Ratnagiri', 'Ganpatipule', 'Alibaug'][i % 3],
      rating: 4.0 + (i % 5) * 0.1,
      reviews: 500 + i * 80,
      price: 3000 + i * 200,
      stars: [3,4,5][i % 3],
      image: 'data:image/jpeg;base64,',
      amenities: ['AC', 'WiFi', 'Pool'],
      description: 'Comfortable stay in prime Konkan location.'
    }))
  ]);

  getHotels(): Observable<Hotel[]> {
    return of(this.hotels()).pipe(delay(500));
  }

  getHotel(id: number): Observable<Hotel | undefined> {
    return of(this.hotels().find(h => h.id === id)).pipe(delay(200));
  }
}
